import { appendFile, access, readFile } from 'node:fs/promises';
import { constants } from 'node:fs';

const headersPath = new URL('../dist/_headers', import.meta.url);
const stagingHeaders = `

# Staging only — generated by npm run build:staging
/*
  X-Robots-Tag: noindex, nofollow
`;

await access(headersPath, constants.F_OK);
const currentHeaders = await readFile(headersPath, 'utf8');

if (!currentHeaders.includes('X-Robots-Tag: noindex, nofollow')) {
  await appendFile(headersPath, stagingHeaders, 'utf8');
}

console.log('Applied staging noindex headers to dist/_headers.');
